package com.Fahim101.tomquiz.utils

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Test

/**
 * Cross-validation of [RequestSigner] against the **server's own** implementation.
 *
 * The vectors below were generated by `ttboost-api/scripts/gen-signature-vectors.mjs`,
 * which imports the real `ttboost-api/lib/signature.js` — the exact code that will
 * verify the APK's requests. So this is not "does my Kotlin look right", it is
 * "does my Kotlin produce the same bytes as the thing that will check it".
 *
 * Regenerate with:
 *
 *     cd ttboost-api
 *     node --import ./scripts/register-esm-hook.mjs scripts/gen-signature-vectors.mjs
 *
 * The vectors deliberately cover the cases where a hand-written canonicaliser
 * drifts from `JSON.stringify`:
 *
 *  - keys that must be re-sorted (nested objects included),
 *  - `5.0` which JavaScript prints as `5` (JS has one number type; Kotlin does not),
 *  - a `/` inside a URL, which must NOT be escaped,
 *  - JSON `null` (Android's `JSONObject.NULL`, a sentinel rather than a real null),
 *  - empty array / empty object / empty string,
 *  - quotes, backslashes, newlines and tabs inside string values.
 *
 * Note this also pins [Constants.TTBOOST_APP_KEY]: every expected signature was
 * computed with the server's `.env` APP_KEY, so if the two ever disagree — the most
 * likely way to break signing during a key rotation — these tests fail loudly
 * instead of the app failing at runtime with an opaque `InvalidSignature`.
 */
class RequestSignerTest {

    private data class Vector(
        val name: String,
        val method: String,
        val path: String,
        val body: String,
        val canonical: String,
        val signature: String,
    )

    private val timestamp = "1700000000"
    private val nonce = "abcdef0123456789"

    // ---- generated by scripts/gen-signature-vectors.mjs — do not edit by hand ----
    // APP_KEY  = base64:dGhpcy1pcy1hLWRldi1vbmx5LWtleS1jaGFuZ2UtbWU=
    // keyBytes = 746869732d69732d612d6465762d6f6e6c792d6b65792d6368616e67652d6d65

    private val vectors = listOf(
        Vector(
            name = "GET, no body (server signs {})",
            method = "GET",
            path = "api/v6/me",
            body = "{}",
            canonical = "{}",
            signature = "d538a92ec1de0e0f4e2afb6a70d3b9f33fa433d5f2bd8f2ffac52718c286a5c7",
        ),
        Vector(
            name = "POST login",
            method = "POST",
            path = "api/v6/login",
            body = "{\"device_name\":\"android\",\"id\":\"demo@ttboost.app\",\"username\":\"demo_user\"}",
            canonical = "{\"device_name\":\"android\",\"id\":\"demo@ttboost.app\",\"username\":\"demo_user\"}",
            signature = "3065a2d6b5662a8ec71928744f2702695db30cc457f6b677417f078775fbd895",
        ),
        Vector(
            name = "POST coins/check (numeric order_id)",
            method = "POST",
            path = "api/v6/coins/check",
            body = "{\"order_id\":42,\"sec_uid\":\"MS4wLjABAAAA\",\"tt_username\":\"demo_user\",\"tiktok_username\":\"target\"}",
            canonical = "{\"order_id\":42,\"sec_uid\":\"MS4wLjABAAAA\",\"tiktok_username\":\"target\",\"tt_username\":\"demo_user\"}",
            signature = "532579657bc98c371d4cd862d06cba25df5d69775ec6e904eb516d1ab6cb5c9a",
        ),
        Vector(
            name = "POST orders with a query string in the path",
            method = "POST",
            path = "api/v6/orders?page=1",
            body = "{\"sec_uid\":\"MS4wLjABAAAA\",\"username\":\"demo_user\",\"url\":\"https://www.tiktok.com/@demo_user\",\"product_id\":\"2\"}",
            canonical = "{\"product_id\":\"2\",\"sec_uid\":\"MS4wLjABAAAA\",\"url\":\"https://www.tiktok.com/@demo_user\",\"username\":\"demo_user\"}",
            signature = "e2164f45186024996315266d553bb97e3061974c5b47717d27649e57603bda38",
        ),
        Vector(
            name = "nested + array + null + bool + numbers",
            method = "POST",
            path = "api/v6/mixed",
            body = "{\"url\":\"https://example.com/a/b\",\"list\":[1,2,3],\"nested\":{\"b\":1,\"a\":2},\"nul\":null,\"flag\":true,\"float\":1.5,\"whole\":5}",
            canonical = "{\"flag\":true,\"float\":1.5,\"list\":[1,2,3],\"nested\":{\"a\":2,\"b\":1},\"nul\":null,\"url\":\"https://example.com/a/b\",\"whole\":5}",
            signature = "239b9ab771b8bf4d4b12a317c79f7d8bb594f999413a508dd4e2b2ab2317d51f",
        ),
        Vector(
            name = "whole-number float must not become 5.0",
            method = "POST",
            path = "api/v6/numbers",
            body = "{\"int\":5,\"double\":5.0,\"big\":1234567890,\"small\":0.25}",
            canonical = "{\"big\":1234567890,\"double\":5,\"int\":5,\"small\":0.25}",
            signature = "f0bbc0bc0c5f1b55b97607317c0fac83460aee741460bc3ff4af8cb2f0dec89c",
        ),
        Vector(
            name = "string escapes: quote, backslash, newline, tab",
            method = "POST",
            path = "api/v6/strings",
            body = "{\"quoted\":\"say \\\"hi\\\"\",\"slash\":\"a\\\\b\",\"multi\":\"line1\\nline2\",\"tabbed\":\"a\\tb\"}",
            canonical = "{\"multi\":\"line1\\nline2\",\"quoted\":\"say \\\"hi\\\"\",\"slash\":\"a\\\\b\",\"tabbed\":\"a\\tb\"}",
            signature = "17f17ccfb57939066d794e3fe7a869f03126a663bb64461cf8d4e9229a8ef5a1",
        ),
        Vector(
            name = "empty string and null-valued key",
            method = "POST",
            path = "api/v6/edge",
            body = "{\"empty\":\"\",\"nothing\":null,\"list\":[],\"obj\":{}}",
            canonical = "{\"empty\":\"\",\"list\":[],\"nothing\":null,\"obj\":{}}",
            signature = "be47623958783ee42bf3f2064ab7ce62fd8295acc2700dc7a50d86ac949096bf",
        ),
    )

    @Test
    fun `canonical json reproduces the server byte for byte`() {
        for (v in vectors) {
            assertEquals(
                "canonical JSON mismatch for '${v.name}'",
                v.canonical,
                RequestSigner.canonicalJson(JSONObject(v.body))
            )
        }
    }

    @Test
    fun `signature reproduces the server byte for byte`() {
        for (v in vectors) {
            assertEquals(
                "signature mismatch for '${v.name}'",
                v.signature,
                RequestSigner.signatureFor(v.method, v.path, JSONObject(v.body), timestamp, nonce)
            )
        }
    }

    /** A GET sends no body; the server still signs the canonical form of `{}`. */
    @Test
    fun `null body is signed as an empty object`() {
        assertEquals(
            RequestSigner.signatureFor("GET", "api/v6/me", JSONObject(), timestamp, nonce),
            RequestSigner.signatureFor("GET", "api/v6/me", null, timestamp, nonce)
        )
    }

    /** The query string must not reach the signature — the server strips it too. */
    @Test
    fun `query string is excluded from the signed path`() {
        val body = JSONObject("{\"a\":1}")
        assertEquals(
            RequestSigner.signatureFor("GET", "api/v6/me/orders", body, timestamp, nonce),
            RequestSigner.signatureFor("GET", "api/v6/me/orders?page=3&per_page=20", body, timestamp, nonce)
        )
    }

    /** The app key constant must match the server's APP_KEY. */
    @Test
    fun `app key is the expected dev key`() {
        assertEquals(
            "Constants.TTBOOST_APP_KEY no longer matches the server's .env APP_KEY",
            "base64:dGhpcy1pcy1hLWRldi1vbmx5LWtleS1jaGFuZ2UtbWU=",
            Constants.TTBOOST_APP_KEY
        )
    }

    /** Headers must be complete and carry a fresh 16-hex-digit nonce each time. */
    @Test
    fun `headers are complete and nonces are unique`() {
        val first = RequestSigner.headers("GET", "/api/v6/me", null)
        val second = RequestSigner.headers("GET", "/api/v6/me", null)

        assertEquals(setOf("X-Signature", "X-Timestamp", "X-Nonce"), first.keys)
        assertEquals(64, first["X-Signature"]!!.length)
        assertEquals(16, first["X-Nonce"]!!.length)
        assertEquals(10, first["X-Timestamp"]!!.length) // seconds, not milliseconds
        assertNotEquals(first["X-Nonce"], second["X-Nonce"])
    }
}
